//! macOS: a Seatbelt profile applied through `/usr/bin/sandbox-exec`, `setsid` plus `killpg` for
//! the process tree. The profile is generated by [`crate::seatbelt`] (pure text, unit-tested on
//! every platform); this module only runs it.
//!
//! **Compiled here, never executed on macOS by the author.** See the README's list of what a
//! real Mac must confirm.

mod spawn;

use std::os::fd::AsRawFd;
use std::sync::OnceLock;

use tokio::process::Command;

use super::rlimits::{self, RlimitContext, RlimitSpec};
use super::unix::{StatusPipe, start};
use super::{Launch, LaunchSpec};
use crate::capabilities::{Capabilities, Capability};
use crate::error::{Dimension, Error, Result};
use crate::normalize::ResolvedPolicy;
use crate::policy::NetworkPolicy;
use crate::report::{DimensionReport, Enforcement};
use crate::seatbelt::{self, Profile};

pub(crate) use super::unix::{Child, TreeKiller};

/// A policy with its profile built, ready to hand to `sandbox-exec`.
pub(crate) struct Prepared {
    enforcement: Enforcement,
    policy: ResolvedPolicy,
    profile: Profile,
    rlimits: Vec<RlimitSpec>,
}

/// Whether `sandbox-exec` exists and can apply a profile from this process. It cannot when this
/// process is itself sandboxed (Seatbelt does not nest) or when the tool was removed.
fn seatbelt_works() -> &'static std::result::Result<(), String> {
    static WORKS: OnceLock<std::result::Result<(), String>> = OnceLock::new();
    WORKS.get_or_init(|| {
        let out = std::process::Command::new(seatbelt::SANDBOX_EXEC)
            .args(["-p", "(version 1)(allow default)", "/usr/bin/true"])
            .output()
            .map_err(|e| format!("{} cannot be run: {e}", seatbelt::SANDBOX_EXEC))?;
        if out.status.success() {
            Ok(())
        } else {
            Err(format!(
                "{} could not apply a trivial profile (already inside a sandbox?): {}",
                seatbelt::SANDBOX_EXEC,
                String::from_utf8_lossy(&out.stderr).trim()
            ))
        }
    })
}

fn degraded_network(requested: &str) -> DimensionReport {
    DimensionReport::degraded(
        &[],
        format!(
            "requested network {requested} cannot be enforced (Seatbelt filters by IP and port, not by host name); running with unrestricted network because the policy allows degrading it"
        ),
    )
}

/// Builds the profile, or fails with `Unavailable` when Seatbelt cannot enforce the policy.
pub(crate) fn prepare(policy: &ResolvedPolicy) -> Result<Prepared> {
    let mut effective = policy.clone();
    let fs = match seatbelt_works() {
        Ok(()) => DimensionReport::enforced(
            &["seatbelt"],
            format!(
                "sandbox-exec with a deny-default profile: {} read-only and {} read-write grants plus the system runtime; everything else (read, write, create, delete, rename) is denied. File metadata (stat) of other paths stays visible",
                policy.ro.len(),
                policy.rw.len()
            ),
        ),
        Err(why) if policy.degraded.fs => DimensionReport::degraded(
            &[],
            format!(
                "{why}; running without filesystem confinement because the policy allows degrading it"
            ),
        ),
        Err(why) => return Err(Error::unavailable(Dimension::Fs, why.clone())),
    };
    let network = match &policy.network {
        NetworkPolicy::Off => DimensionReport::enforced(
            &["seatbelt"],
            "no network rules in the profile: sockets cannot connect, bind or send",
        ),
        NetworkPolicy::Loopback => DimensionReport::enforced(
            &["seatbelt"],
            "bind, inbound and outbound allowed for localhost only",
        ),
        NetworkPolicy::On => DimensionReport::unrestricted("network unrestricted by request"),
        NetworkPolicy::Allowlist(hosts) => {
            if policy.degraded.network {
                effective.network = NetworkPolicy::Off;
                degraded_network(&format!("allowlist of {} host(s)", hosts.len()))
            } else {
                return Err(Error::unavailable(
                    Dimension::Network,
                    "Seatbelt cannot filter by host name; that needs an egress proxy outside hx-sandbox",
                ));
            }
        }
    };
    // macOS ignores RLIMIT_AS, counts RLIMIT_NPROC per user over every process the user already
    // has (a logged-in user has hundreds, so the raw allowance alone left a sandboxed shell unable
    // to fork: EAGAIN), and exempts uid 0 from it. The allowance goes on top of the processes that
    // exist now, as on Linux.
    let context = RlimitContext {
        baseline_tasks: super::unix_sys::process_count(),
        enforces_address_space: false,
        enforces_process_count: super::unix_sys::effective_uid() != 0,
    };
    let mut limits = rlimits::plan(&policy.resources, policy.kill_grace, context);
    // The raised process count must stay within this process's own hard limit, which only root
    // may raise (macOS's per-user ceiling, kern.maxprocperuid, clamps it again in the kernel).
    if let Some(ceiling) = super::unix_sys::hard_limit(libc::RLIMIT_NPROC) {
        for spec in limits.iter_mut().filter(|s| s.name == "nproc") {
            spec.soft = spec.soft.min(ceiling);
            spec.hard = spec.hard.min(ceiling);
        }
    }
    let enforcement = Enforcement {
        platform: "macos".to_owned(),
        fs,
        network,
        env: DimensionReport::enforced(
            &["env_clear+allowlist"],
            format!(
                "the child sees exactly {} variable(s): the allowlist that is set here plus env_set",
                policy.env.len()
            ),
        ),
        process: DimensionReport::enforced(
            &["setsid+killpg", "timeout", "output-cap", "rlimits"],
            format!(
                "the tree is killed through its process group, so a descendant that calls setsid or setpgid can outlive a kill; no seccomp-style syscall filter exists on macOS beyond the profile; rlimits: {}",
                rlimits::describe(&limits, &policy.resources, context)
            ),
        ),
    };
    let profile = seatbelt::build(&effective);
    Ok(Prepared {
        enforcement,
        policy: effective,
        profile,
        rlimits: limits,
    })
}

impl Prepared {
    /// The report for the child this will start.
    pub(crate) fn enforcement(&self) -> &Enforcement {
        &self.enforcement
    }

    /// Starts the program under `sandbox-exec`.
    pub(crate) fn spawn(self, spec: LaunchSpec<'_>) -> Result<Launch> {
        let status = StatusPipe::new()?;
        let inherit_fd = match &spec.inherit {
            Some(fd) if fd.as_raw_fd() < 3 => {
                return Err(Error::invalid(
                    "the inherited descriptor must be numbered 3 or higher (0-2 are stdio)",
                ));
            }
            Some(fd) => fd.as_raw_fd(),
            None => -1,
        };
        let mut cmd = Command::new(seatbelt::SANDBOX_EXEC);
        cmd.args(self.profile.exec_args(spec.program, spec.args))
            .env_clear()
            .current_dir(&self.policy.cwd);
        for (key, value) in &self.policy.env {
            cmd.env(key, value);
        }
        spawn::install(&mut cmd, inherit_fd, status.write.as_raw_fd(), self.rlimits);
        let launch = start(cmd, spec.stdin, Some(status), spawn::step_name, None);
        drop(spec.inherit);
        launch
    }
}

/// What this host can enforce.
pub(crate) fn capabilities() -> Capabilities {
    let works = seatbelt_works();
    let fs = match works {
        Ok(()) => Capability::yes("seatbelt", "sandbox-exec applied a trivial profile"),
        Err(why) => Capability::no(Some("seatbelt"), why.clone()),
    };
    let net_off = match works {
        Ok(()) => Capability::yes("seatbelt", "no network rules in the profile"),
        Err(why) => Capability::no(Some("seatbelt"), why.clone()),
    };
    let net_loopback = match works {
        Ok(()) => Capability::yes("seatbelt", "localhost-only network rules"),
        Err(why) => Capability::no(Some("seatbelt"), why.clone()),
    };
    Capabilities {
        platform: "macos".to_owned(),
        os_version: std::process::Command::new("/usr/bin/sw_vers")
            .arg("-productVersion")
            .output()
            .ok()
            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned()),
        fs,
        network_off: net_off,
        network_loopback: net_loopback,
        network_allowlist: Capability::no(
            None,
            "Seatbelt filters by IP and port, not by host name; needs an egress proxy",
        ),
        // Only the process group: a descendant that calls setsid or setpgid outlives a kill, so the
        // capability is not claimed (the run itself still goes ahead and its report says so).
        process_tree_kill: Capability::no(
            Some("setsid+killpg"),
            "descendants that leave the process group are not reached",
        ),
        inherited_handle: Capability::yes(
            "fd",
            "one descriptor numbered 3 or higher keeps its number in the child",
        ),
    }
}
